// Des: Tests for sy-clou-sync: local first, offline queue drains, restore
// Flo: store pages locally > sync to the mock cloud > go offline > queue stays > come back > drain > restore from the pack
// I/O: mock cloud + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const hash = @import("ut-hash-dedu.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, srv2: mock.Mock, cldz: cmok.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv2.sta2(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cldz = cmok.Mock.init(allo); self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cldz.store(), .sql2 = self.cldz.sql2() }; }
pub fn down(self: *Rigg) void { self.cldz.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv2.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn page(self: *Rigg, path: []const u8) !pipe.Outc { var buf4: [64]u8 = undefined; return pipe.pageFetc(allo, self.aren.allocator(), std.testing.io, .{}, &self.dbzz, self.dirz, self.srv2.urlzOfzz(&buf4, path), true); } };
const NOWZ: i64 = 1790000000000;
test "local first: pages are queued, one sync uploads 1 pack + rows, queue empties" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.page("/p1"); _ = try rig3.page("/p2"); _ = try rig3.page("/p3"); try std.testing.expectEqual(@as(i64, 6), try outb.outbCont(&rig3.dbzz, 0)); const nowz = pipe.nowzMill(std.testing.io) + 1000; const rslt = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz); try std.testing.expectEqual(@as(u32, 3), rslt.recs); try std.testing.expectEqual(@as(u32, 3), rslt.fil2); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.map.count()); try std.testing.expect(std.mem.startsWith(u8, rslt.pack, "runs/")); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig3.dbzz, 0)); try std.testing.expectEqual(@as(usize, 3), rig3.cldz.sawzStmt("INTO cl_page")); try std.testing.expectEqual(@as(usize, 3), rig3.cldz.sawzStmt("INTO cl_manif")); const agai = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz); try std.testing.expectEqual(@as(u32, 0), agai.fil2 + agai.recs); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.map.count()); }
test "offline cloud: nothing lost, nothing burned; the first online sync drains everything" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.page("/p1"); _ = try rig3.page("/p2"); rig3.cldz.offl = true; const nowz = pipe.nowzMill(std.testing.io) + 1000; try std.testing.expectError(error.CloudSql, sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz)); try std.testing.expectEqual(@as(i64, 4), try outb.outbCont(&rig3.dbzz, 0)); rig3.cldz.offl = false; const late = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz + 1000); try std.testing.expectEqual(@as(u32, 2), late.fil2); try std.testing.expectEqual(@as(u32, 2), late.recs); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig3.dbzz, 0)); }
test "SQL down after the pack upload: files stay queued and are retried" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.page("/p1"); const nowz = pipe.nowzMill(std.testing.io) + 1000; rig3.cldz.sqlo = true; try std.testing.expectError(error.CloudSql, sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz)); try std.testing.expectEqual(@as(i64, 2), try outb.outbCont(&rig3.dbzz, 0)); rig3.cldz.sqlo = false; const rslt = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), nowz + 3 * 3600000); try std.testing.expectEqual(@as(u32, 1), rslt.fil2); }
test "restore reads a page back from the cloud pack, hash checked" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const out2 = try rig3.page("/p2"); _ = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), pipe.nowzMill(std.testing.io) + 1000); var hxzz: hash.Hexz = undefined; @memcpy(&hxzz, out2.hexz[0..64]); const body = try sync.res3(&rig3.synz, rig3.aren.allocator(), hxzz); try std.testing.expect(std.mem.indexOf(u8, body, "Item 2 page text") != null); const bogu = hash.hashHexz("nothing"); try std.testing.expectError(error.NotFound, sync.res3(&rig3.synz, rig3.aren.allocator(), bogu)); }
test "hostile text goes through escaped, never raw into SQL" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try inde.pageSetz(&rig3.dbzz, "http://a/x'; DROP TABLE cl_page;--", .{ .hexz = "aa", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); try inde.recoSetz(&rig3.dbzz, "http://a/x'; DROP TABLE cl_page;--", .{ .hexz = "aa", .kind = "text", .body = "it's" }, 1); try outb.outbAddz(&rig3.dbzz, "rec", "http://a/x'; DROP TABLE cl_page;--", 1, true); _ = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(rig3.cldz.sawzStmt("x''; DROP TABLE cl_page;--") >= 1); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.sawzStmt("x'; DROP")); }
